//! LEGENDARY sound signatures + juice (bd_sim `constructs/legend.rs`; visuals are `present::legend`).
//! Sounds are generated by `tools/sfxgen/sounds_legend.py` (dry, carved by role, in the baked loudness
//! hierarchy); the big moments go through the existing juice channels (`HitStop`, `HitFreeze`,
//! `CameraShakeEvent`, `FovPunch`) sized from the `assets/tuning/juice.ron` tiers.
//!
//! | `HeldFx` | sound | juice |
//! |---|---|---|
//! | `RecallStart` | `recall_whoosh` (2D for the catcher: it rushes at you) | |
//! | `Catch` (strength ≥ 2) | `recall_catch` — THE catch snap | local catcher: Light hit-stop (+ the item holds), Medium punch trauma, Medium nudge-zoom |
//! | `Lodge` | `lodge_thunk` | |
//! | `ThorFlight` | `thor_flight_loop` on the item while it drags you | |
//! | `StormRaise` | `storm_raise` / `storm_fizzle` (strength 0) | |
//! | `StormMark` | `storm_mark` (icicles a fifth up), meteors: `storm_meteor_whistle`, timed to land | |
//! | `StormStrike` | per element (`StormKind::of`): `storm_bolt`, `storm_meteor_hit`, `storm_icicle`, `storm_tornado`, `storm_geyser`, `storm_crush`, `storm_spikes`, `storm_maw`, `storm_nova`, `storm_miasma` | camera shake by distance |
//! | `StormArc` | `storm_arc` | |
//! | `Ricochet` | `ricochet_ding`, up the E-minor pentatonic per bounce | |
//! | `Parry` (Blade + Fast) | `saber_deflect` (layered on the generic parry ting) | |
//! | `SwingStart` (energy blade) | `saber_swoosh` by swing strength; idle `saber_hum_loop` pitched / swelled by blade speed | |
//! | `Wave` | `blade_wave` (bigger = lower) + `blade_wave_loop` flying with the crescent | |
//! | `LeapStart` / `LeapSlam` | `leap_whoosh` / `leap_slam` | slam: shake by distance; the leaper: Heavy hit-stop + Heavy nudge-zoom |
//! | `Armor` | `armor_clang` | the armoured local wielder: a small shake |
//! | `ChainSweep` / `ChainPull` | `chain_sweep` (+ `chain_fire_roar` for Fire) / `chain_pull` | |
//! | `OneShot` | `golden_gun` (over the gun's own report) | |
//! | `NeedleStick` / `Supercombine` | `needle_tick` up the pentatonic per needle / `supercombine` | |
//! | `GravGrab` / `GravPunt` | `grav_grab` / `grav_punt` (empty-handed blast lower) | |
//! | `StreamLatch` / `StreamRelease` | `stream_snap` + `stream_loop` while latched / `stream_snap` | |
//! | `GunCharge` | charge cannon: `gun_charge_loop` rising E → B, `gun_charge_full`; BFG: `bfg_spinup` | |
//! | `ChargeShot` | `charge_shot_tap` … `charge_shot_blast` by charge | |
//! | `BfgZap` | `bfg_zap` | |
//!
//! Hits (storm strikes, the leap cleave, the one-shot round, the supercombine burst) already carry the
//! sim's `with_impact` weight into `GameEvent::Hit`, which `present::impact::connect` tiers into
//! hit-stop / victim shake / punch (the test below pins that they land Heavy or above).

use super::constructs::ConstructEntities;
use super::impact::HitFreeze;
use super::impact::connect::JuiceTuningRes;
use super::sound::{Sfx3d, SfxLoopEmitter};
use super::{PresentSet, bv};
use crate::juice::{CameraShakeEvent, FovPunch, HitStop};
use crate::sim_bridge::{ActiveWorld, GameEvents};
use bd_core::ConstructId;
use bd_core::mechanics::{Element, FormCategory};
use bd_sim::GameEvent;
use bd_sim::constructs::legend::{self as lg, StormKind};
use bd_sim::constructs::{AnimState, Construct};
use bd_sim::events::HeldFx;
use bevy::prelude::*;

/// E-minor pentatonic steps (semitones) for rising ricochet / needle pitches.
const PENT: [f32; 8] = [0.0, 3.0, 5.0, 7.0, 10.0, 12.0, 15.0, 17.0];

fn pent_pitch(step: usize) -> f32 {
    2f32.powf(PENT[step.min(PENT.len() - 1)] / 12.0)
}

/// An energy blade (a lightsaber by any other name): Blade + Fast, Electric or Light.
pub fn energy_blade(c: &Construct) -> bool {
    lg::swing_deflects(c) && matches!(c.recipe.element, Element::Electric | Element::Light)
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum LoopKind {
    /// Energy-blade idle hum (follows the item; pitch / gain from blade speed).
    Hum,
    /// Recall flight rush (follows the item until it is caught / stops).
    Thor,
    /// Proton stream latched (follows the gun while it streams).
    Stream,
    /// Charge-cannon charging (follows the gun; pitch rises E → B).
    Charge,
    /// A flying crescent (moves on its own).
    Wave,
}

impl LoopKind {
    fn sound(self) -> &'static str {
        match self {
            LoopKind::Hum => "saber_hum_loop",
            LoopKind::Thor => "thor_flight_loop",
            LoopKind::Stream => "stream_loop",
            LoopKind::Charge => "gun_charge_loop",
            LoopKind::Wave => "blade_wave_loop",
        }
    }
    /// Hard cap (s) so a missed stop event can never leave a loop running.
    fn max_age(self) -> f32 {
        match self {
            LoopKind::Hum => f32::INFINITY,
            LoopKind::Thor => 8.0,
            LoopKind::Stream => 4.0,
            LoopKind::Charge => 10.0,
            LoopKind::Wave => 3.0,
        }
    }
}

struct Voice {
    kind: LoopKind,
    id: ConstructId,
    entity: Entity,
    age: f32,
    /// Wave: world velocity and lifetime (s).
    vel: Vec3,
    life: f32,
    /// Blade speed tracking (hum): last position, smoothed speed (m/s).
    last: Option<Vec3>,
    speed: f32,
    /// Charge: full charge reached (pitch holds at the top).
    full: bool,
    stop: bool,
}

#[derive(Resource, Default)]
struct LegendAudio {
    voices: Vec<Voice>,
    /// Delayed one-shots (real seconds left).
    pending: Vec<(f32, Sfx3d)>,
}

impl LegendAudio {
    fn start(&mut self, commands: &mut Commands, kind: LoopKind, id: ConstructId, at: Vec3, gain: f32) -> usize {
        if let Some(i) = self.voices.iter().position(|v| v.kind == kind && v.id == id && !v.stop && kind != LoopKind::Wave) {
            self.voices[i].age = 0.0;
            return i;
        }
        let mut em = SfxLoopEmitter::new(kind.sound());
        em.gain = gain;
        let entity = commands.spawn((Name::new("legend_loop"), Transform::from_translation(at), em)).id();
        self.voices.push(Voice { kind, id, entity, age: 0.0, vel: Vec3::ZERO, life: 0.0, last: None, speed: 0.0, full: false, stop: false });
        self.voices.len() - 1
    }
    fn stop(&mut self, kind: LoopKind, id: ConstructId) {
        for v in self.voices.iter_mut().filter(|v| v.kind == kind && v.id == id) {
            v.stop = true;
        }
    }
}

pub struct LegendSoundPlugin;

impl Plugin for LegendSoundPlugin {
    fn build(&self, app: &mut App) {
        app.init_resource::<LegendAudio>()
            .add_message::<Sfx3d>()
            .add_message::<CameraShakeEvent>()
            .add_message::<FovPunch>()
            .add_message::<HitStop>()
            .add_systems(Update, legend_events.in_set(PresentSet::Events))
            .add_systems(Update, legend_loops.in_set(PresentSet::Sync));
    }
}

/// Camera shake falloff: 1 at the spot, 0 at `range` m.
fn near(eye: Vec3, p: Vec3, range: f32) -> f32 {
    (1.0 - eye.distance(p) / range).clamp(0.0, 1.0)
}

#[allow(clippy::too_many_arguments)]
fn legend_events(
    mut commands: Commands,
    time: Res<Time<Real>>,
    mut events: MessageReader<GameEvents>,
    active: Option<Res<ActiveWorld>>,
    juice: Option<Res<JuiceTuningRes>>,
    mut freeze: Option<ResMut<HitFreeze>>,
    mut st: ResMut<LegendAudio>,
    out: (MessageWriter<Sfx3d>, MessageWriter<CameraShakeEvent>, MessageWriter<FovPunch>, MessageWriter<HitStop>),
    cam: Query<&GlobalTransform, With<crate::camera::PlayerCamera>>,
) {
    let (mut sfx, mut shake, mut fov, mut stop) = out;
    let dt = time.delta_secs();
    // Delayed one-shots (telegraphs timed to land with the strike).
    let mut i = 0;
    while i < st.pending.len() {
        st.pending[i].0 -= dt;
        if st.pending[i].0 <= 0.0 {
            let (_, s) = st.pending.swap_remove(i);
            sfx.write(s);
        } else {
            i += 1;
        }
    }
    let Some(active) = active else {
        events.clear();
        st.pending.clear();
        return;
    };
    let jt = juice.map(|j| j.0.clone()).unwrap_or_default();
    let t = active.world.cfg.tuning.legendary;
    let eye = cam.single().map(|g| g.translation()).unwrap_or(Vec3::ZERO);
    // One telegraph per storm call (rains mark every drop in the same tick).
    let mut marked: Vec<ConstructId> = Vec::new();
    for ev in events.read() {
        let GameEvent::HeldFx { id, owner, fx, pos, dir, strength } = &ev.event else { continue };
        let (id, s) = (*id, *strength);
        let p = bv(*pos);
        let d = bv(*dir).normalize_or_zero();
        let mine = active.local == Some(*owner);
        let c = active.world.constructs.get(id);
        let element = c.map(|c| c.recipe.element);
        let at = |name: &'static str| Sfx3d::at(name, p);
        match fx {
            // ---------------------------------------------------------------- recall
            HeldFx::RecallStart => {
                // The catcher hears it coming at them; everyone else hears it leave the wall.
                sfx.write(if mine { Sfx3d::ui("recall_whoosh").gain(0.8) } else { at("recall_whoosh") });
            }
            HeldFx::Catch if s >= 2.0 => {
                sfx.write(if mine { Sfx3d::ui("recall_catch") } else { at("recall_catch") });
                st.stop(LoopKind::Thor, id);
                if mine {
                    let secs = jt.hitstop[0];
                    stop.write(HitStop { secs });
                    if let Some(f) = freeze.as_deref_mut() {
                        f.hold_construct(id, secs);
                    }
                    shake.write(CameraShakeEvent { trauma: jt.punch_trauma[1], dir: d });
                    fov.write(FovPunch { degrees: jt.nudge_zoom[1] });
                }
            }
            HeldFx::Catch => st.stop(LoopKind::Thor, id),
            HeldFx::Lodge => {
                sfx.write(at("lodge_thunk"));
            }
            HeldFx::ThorFlight => {
                sfx.write(at("recall_whoosh").pitch(0.8));
                st.start(&mut commands, LoopKind::Thor, id, p, 1.0);
            }
            // ---------------------------------------------------------------- call the storm
            HeldFx::StormRaise => {
                sfx.write(at(if s >= 1.0 { "storm_raise" } else { "storm_fizzle" }));
            }
            HeldFx::StormMark => {
                if marked.contains(&id) {
                    continue;
                }
                marked.push(id);
                let kind = element.and_then(StormKind::of);
                let (name, pitch, len) = match kind {
                    Some(StormKind::Meteors) => ("storm_meteor_whistle", 1.0, 0.55),
                    Some(StormKind::Icicles) => ("storm_mark", 1.5, 0.52 / 1.5),
                    _ => ("storm_mark", 1.0, 0.52),
                };
                let delay = (s - len).max(0.0);
                let one = Sfx3d::at(name, p).pitch(pitch);
                if delay > 0.01 {
                    st.pending.push((delay, one));
                } else {
                    sfx.write(one);
                }
            }
            HeldFx::StormStrike => {
                let kind = element.and_then(StormKind::of);
                let drop = d.y < -0.5;
                let (name, gain, trauma, range) = match kind {
                    Some(StormKind::Bolt) => ("storm_bolt", 1.0, 0.55, 70.0),
                    Some(StormKind::Meteors) => ("storm_meteor_hit", 0.9, 0.2, 45.0),
                    Some(StormKind::Icicles) => ("storm_icicle", 0.9, 0.15, 35.0),
                    Some(StormKind::Tornado) if s > t.storm_radius * 1.15 => ("leap_whoosh", 1.1, 0.25, 40.0),
                    Some(StormKind::Tornado) => ("storm_tornado", 1.0, 0.3, 50.0),
                    Some(StormKind::Geyser) => ("storm_geyser", 1.0, 0.35, 50.0),
                    Some(StormKind::Crush) => ("storm_crush", 1.0, 0.5, 60.0),
                    Some(StormKind::Spikes) => ("storm_spikes", 1.0, 0.5, 60.0),
                    Some(StormKind::Maw) => ("storm_maw", 1.0, 0.3, 50.0),
                    Some(StormKind::Nova) => ("storm_nova", 1.0, 0.45, 70.0),
                    Some(StormKind::Miasma) => ("storm_miasma", 1.0, 0.1, 30.0),
                    None if drop => ("storm_meteor_hit", 0.8, 0.15, 40.0),
                    None => ("hit_heavy", 1.0, 0.3, 50.0),
                };
                let pitch = if kind == Some(StormKind::Tornado) && name == "leap_whoosh" { 1.25 } else { 1.0 };
                sfx.write(Sfx3d::at(name, p).gain(gain).pitch(pitch));
                let k = near(eye, p, range);
                if k > 0.0 {
                    shake.write(CameraShakeEvent { trauma: trauma * k, dir: Vec3::NEG_Y });
                }
            }
            HeldFx::StormArc => {
                sfx.write(Sfx3d::at("storm_arc", p + d * (s * 0.5)).gain(0.9));
            }
            // ---------------------------------------------------------------- ricochet
            HeldFx::Ricochet => {
                let step = (s.max(1.0) as usize).saturating_sub(1);
                sfx.write(at("ricochet_ding").pitch(pent_pitch(step)));
            }
            // ---------------------------------------------------------------- deflect / energy blade
            HeldFx::Parry if c.is_some_and(lg::swing_deflects) => {
                sfx.write(at("saber_deflect"));
            }
            HeldFx::SwingStart if c.is_some_and(energy_blade) => {
                // Quick 1, combo 1 + 0.25·k, heavy 2: harder swings are louder and a touch lower.
                let k = ((s - 1.0) / 1.0).clamp(0.0, 1.0);
                sfx.write(at("saber_swoosh").gain(0.75 + 0.45 * k).pitch(1.05 - 0.15 * k));
            }
            // ---------------------------------------------------------------- blade wave
            HeldFx::Wave => {
                let size = s.abs().max(0.2);
                sfx.write(at("blade_wave").pitch((1.0 / size.powf(0.35)).clamp(0.6, 1.3)).gain((0.8 + 0.2 * size).min(1.4)));
                let heavy = c.is_some_and(lg::heavy_blade);
                let speed = lg::wave_speed(&t, heavy).max(1.0);
                let i = st.start(&mut commands, LoopKind::Wave, id, p, (0.6 + 0.2 * size).min(1.2));
                let v = &mut st.voices[i];
                v.vel = d * speed;
                v.life = (t.wave_range / speed).clamp(0.1, 3.0);
            }
            // ---------------------------------------------------------------- heavy blade
            HeldFx::LeapStart => {
                sfx.write(at("leap_whoosh"));
            }
            HeldFx::LeapSlam => {
                sfx.write(at("leap_slam").gain((0.85 + s / 12.0).min(1.3)));
                let k = if mine { 1.0 } else { near(eye, p, 70.0) };
                if k > 0.0 {
                    shake.write(CameraShakeEvent { trauma: 0.7 * k, dir: Vec3::NEG_Y });
                }
                if mine {
                    stop.write(HitStop { secs: jt.hitstop[2] });
                    fov.write(FovPunch { degrees: jt.nudge_zoom[2] });
                }
            }
            HeldFx::Armor => {
                sfx.write(at("armor_clang"));
                if mine {
                    shake.write(CameraShakeEvent { trauma: jt.punch_trauma[0], dir: d });
                }
            }
            // ---------------------------------------------------------------- chain blades
            HeldFx::ChainSweep => {
                sfx.write(at("chain_sweep"));
                if element == Some(Element::Fire) {
                    sfx.write(at("chain_fire_roar"));
                }
            }
            HeldFx::ChainPull => {
                sfx.write(at("chain_pull"));
            }
            // ---------------------------------------------------------------- guns
            HeldFx::OneShot => {
                sfx.write(at("golden_gun"));
            }
            HeldFx::NeedleStick => {
                let step = (s.max(1.0) as usize).saturating_sub(1);
                sfx.write(at("needle_tick").pitch(pent_pitch(step)));
            }
            HeldFx::Supercombine => {
                sfx.write(at("supercombine"));
            }
            HeldFx::GravGrab => {
                sfx.write(at("grav_grab"));
            }
            HeldFx::GravPunt => {
                sfx.write(if s < 0.0 { at("grav_punt").pitch(0.8).gain(1.15) } else { at("grav_punt") });
            }
            HeldFx::StreamLatch => {
                sfx.write(at("stream_snap").pitch(1.25).gain(0.7));
                st.start(&mut commands, LoopKind::Stream, id, p, 1.0);
            }
            HeldFx::StreamRelease => {
                sfx.write(at("stream_snap").gain(if s > 0.0 { 1.0 } else { 0.8 }));
                st.stop(LoopKind::Stream, id);
            }
            HeldFx::GunCharge => {
                if c.is_some_and(lg::bfg) {
                    sfx.write(at("bfg_spinup"));
                } else if s < 0.5 {
                    st.start(&mut commands, LoopKind::Charge, id, p, 0.8);
                } else {
                    sfx.write(at("gun_charge_full"));
                    for v in st.voices.iter_mut().filter(|v| v.kind == LoopKind::Charge && v.id == id) {
                        v.full = true;
                    }
                }
            }
            HeldFx::ChargeShot => {
                st.stop(LoopKind::Charge, id);
                let k = s.clamp(0.0, 1.0);
                if k < 0.05 {
                    sfx.write(at("charge_shot_tap"));
                } else {
                    sfx.write(at("charge_shot_blast").gain(0.5 + 0.6 * k).pitch(1.3 - 0.3 * k));
                    if k < 0.6 {
                        sfx.write(at("charge_shot_tap").gain(1.0 - k));
                    }
                }
            }
            HeldFx::BfgZap => {
                sfx.write(Sfx3d::at("bfg_zap", p + d * (s * 0.5)).gain(0.85));
            }
            _ => {}
        }
    }
}

/// Loop voices: energy-blade hums (found from the world), and the event-started loops following
/// their item / flying with their crescent; stop conditions from the replicated construct state.
#[allow(clippy::too_many_arguments)]
fn legend_loops(
    mut commands: Commands,
    time: Res<Time<Real>>,
    active: Option<Res<ActiveWorld>>,
    map: Option<Res<ConstructEntities>>,
    mut st: ResMut<LegendAudio>,
    gt: Query<&GlobalTransform>,
    mut em: Query<(&mut Transform, &mut SfxLoopEmitter)>,
) {
    let dt = time.delta_secs().max(1e-4);
    let Some(active) = active else {
        for v in st.voices.drain(..) {
            commands.entity(v.entity).try_despawn();
        }
        return;
    };
    let t = active.world.cfg.tuning.legendary;
    // Energy blades held (formed, in hand or flying) get a hum.
    for c in active.world.constructs.iter() {
        if c.category == FormCategory::Held && c.active() && energy_blade(c) && !st.voices.iter().any(|v| v.kind == LoopKind::Hum && v.id == c.id) {
            st.start(&mut commands, LoopKind::Hum, c.id, bv(c.pos), 0.0);
        }
    }
    let item_pos = |id: ConstructId| -> Option<Vec3> {
        let e = map.as_ref().and_then(|m| m.0.get(&id).copied());
        e.and_then(|e| gt.get(e).ok()).map(|g| g.translation()).or_else(|| active.world.constructs.get(id).map(|c| bv(c.center())))
    };
    let charge_span = (t.charge_full - t.charge_min).max(0.05);
    for v in st.voices.iter_mut() {
        v.age += dt;
        let c = active.world.constructs.get(v.id);
        let alive = match v.kind {
            LoopKind::Hum => c.is_some_and(|c| c.active() && energy_blade(c)),
            // Caught (attached again) or stopped flying.
            LoopKind::Thor => c.is_some_and(|c| !c.attached() && (c.anim_state == AnimState::Move || v.age < 0.3)),
            LoopKind::Stream => c.is_some_and(|c| c.anim_state == AnimState::Active || v.age < 0.3),
            LoopKind::Charge => c.is_some_and(|c| c.anim_state == AnimState::Charging || v.age < 0.3),
            LoopKind::Wave => v.age < v.life,
        };
        if !alive || v.age > v.kind.max_age() {
            v.stop = true;
        }
        if v.stop {
            continue;
        }
        let Ok((mut tr, mut e)) = em.get_mut(v.entity) else { continue };
        match v.kind {
            LoopKind::Wave => {
                tr.translation += v.vel * dt;
                // Fades out over its last 0.15 s (the crescent breaks up).
                e.gain = e.gain.min(((v.life - v.age) / 0.15).clamp(0.0, 1.0) * 1.2);
            }
            LoopKind::Hum => {
                let Some(p) = item_pos(v.id) else { continue };
                // Blade speed → a swell and a doppler-ish lift (the swoosh without an event).
                if let Some(last) = v.last {
                    let sp = (p - last).length() / dt;
                    let a = 1.0 - (-dt * 18.0).exp();
                    v.speed += (sp.min(60.0) - v.speed) * a;
                }
                v.last = Some(p);
                tr.translation = p;
                let k = (v.speed / 20.0).clamp(0.0, 1.0);
                let fade_in = (v.age / 0.25).clamp(0.0, 1.0);
                e.gain = (0.7 + 0.6 * k) * fade_in;
                e.pitch = 1.0 + 0.18 * k;
            }
            LoopKind::Charge => {
                if let Some(p) = item_pos(v.id) {
                    tr.translation = p;
                }
                let k = if v.full { 1.0 } else { (v.age / charge_span).clamp(0.0, 1.0) };
                e.pitch = 1.0 + 0.5 * k; // E → B (a consonant fifth)
                e.gain = 0.7 + 0.5 * k;
            }
            LoopKind::Thor | LoopKind::Stream => {
                if let Some(p) = item_pos(v.id) {
                    tr.translation = p;
                }
            }
        }
    }
    st.voices.retain(|v| {
        if v.stop {
            commands.entity(v.entity).try_despawn();
        }
        !v.stop
    });
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::present::impact::connect::{JuiceTuning, Tier, tier};
    use bd_sim::combat::{HitKind, impact_fx};

    /// The legendary hits reach the connect tiers at Heavy or above (hit-stop, victim shake, punch):
    /// the sim's `with_impact` weights survive `impact_fx` into the tiering.
    #[test]
    fn legend_hits_land_heavy() {
        let jt = JuiceTuning::default();
        let t = lg::LegendTuning::default();
        let d = bd_core::Vec3::X;
        // (kind, damage, knockback, impact weight)
        let hits = [
            (HitKind::Explosion, 25.0 * t.storm_dmg * 0.6, t.storm_kb * 0.6, t.storm_impact * 0.6), // storm edge
            (HitKind::Explosion, 20.0 * t.leap_dmg, t.leap_kb, t.leap_impact * 0.5),                 // leap cleave, small
            (HitKind::Shot, t.one_shot_dmg, t.one_shot_kb, 1.0),                                     // the golden round
            (HitKind::Explosion, t.super_dmg, t.super_kb * 0.5, 1.0),                                 // supercombine
        ];
        for (kind, dmg, kb, w) in hits {
            let fx = impact_fx(dmg, kb, w, d, 0.0);
            let tr = tier(&jt, kind, fx.strength, fx.heavy, kb.min(jt.finisher_kb - 1.0), false);
            assert!(tr >= Tier::Heavy, "{kind:?} dmg {dmg} kb {kb} w {w}: strength {} → {tr:?}", fx.strength);
        }
    }

    #[test]
    fn pentatonic_steps_rise() {
        assert_eq!(pent_pitch(0), 1.0);
        assert!((1..8).all(|i| pent_pitch(i) > pent_pitch(i - 1)));
        assert_eq!(pent_pitch(40), pent_pitch(7));
    }
}
